-- B1(2026-11-02):agent 会话「按 bot+user+status 取最近」的查找索引。
-- 与 packages/database/src/schema/agent-runtime.ts 的 lookupIdx 对齐;
-- 纯索引,不改表结构、不回填数据,可重复执行。
CREATE INDEX IF NOT EXISTS ix_agent_runtime_sessions_lookup
  ON agent_runtime_sessions (bot_id, user_id, status, updated_at DESC);
